descriptor.controllerScript:
self.onInit = function() {
    self.ctx.$scope.status;
    self.ctx.$scope.signal;
    self.ctx.$scope.type;
    self.ctx.$scope.modelNumber;    
    self.ctx.$scope.image;
    self.ctx.$scope.serialNumber;
    self.ctx.$scope.description;
    self.ctx.$scope.department;    
    self.ctx.$scope.lastActivityTime;
};

self.onDataUpdated = function() {
    self.ctx.data.forEach(x=>{
        if(x.dataKey.name == "status"){
            self.ctx.$scope.status = x.data[0][1] == "true" ? true : false;
        }
        if(x.dataKey.name == "image"){
            self.ctx.$scope.image = x.data[0][1];
        }
        if(x.dataKey.name == "type"){
            self.ctx.$scope.type = x.data[0][1];
        }
        if(x.dataKey.name == "modelNumber"){
            self.ctx.$scope.modelNumber = x.data[0][1];
        }
        if(x.dataKey.name == "serialNumber"){
            self.ctx.$scope.serialNumber = x.data[0][1];
        }
        if(x.dataKey.name == "description"){
            self.ctx.$scope.description = x.data[0][1];
        }
        if(x.dataKey.name == "department"){
            self.ctx.$scope.department = x.data[0][1];
        }
        if(x.dataKey.name == "lastActivityTime"){
            self.ctx.$scope.lastActivityTime = x.data[0][1] ? moment(x.data[0][1]).format("DD.MM.yyyy HH:mm") : "No Data";
        }
        if(x.dataKey.name == "rssi"){
            if(x.data[0][1] && x.data[0][1] <= -110){
                self.ctx.$scope.signal = "signal1";
            } else if(x.data[0][1] && x.data[0][1] > -110 && x.data[0][1] <= -90){
                self.ctx.$scope.signal = "signal2";
            } else if(x.data[0][1] && x.data[0][1] > -90 && x.data[0][1] <= -70){
                self.ctx.$scope.signal = "signal3";
            } else if(x.data[0][1] && x.data[0][1] >= -70){
                self.ctx.$scope.signal = "signal4";
            } else {
                self.ctx.$scope.signal = "signal0";
            }
            self.ctx.$scope.serialNumber = x.data[0][1];
        }
    })
    self.ctx.detectChanges();
}

self.onResize = function() {

}

self.onDestroy = function() {
}

